// Prüf-Aufträge (SHOPIFY 5, Migration 109): Dateien endgültig gelöschter Papierkorb-Elemente – Schritt 1: jede Datei zuerst prüfen.
// Eingang (von ALLY 20, Pfade nur aus der Datenbank): { token, auftrag, dateien: [pfad] }. Nur Bereich ally, nur Pfade nach den Regeln von SPEICHER 1
// (relativ, höchstens 1000 Zeichen, keine leeren/„.“/„..“-Teile, Teile höchstens 255 Zeichen, keine Steuer- oder Platzhalterzeichen) mit Endung .pdf/.csv.
// Höchstens 200 Dateien je Durchgang (Zeit); die übrigen Elemente bleiben im Papierkorb und werden beim nächsten Löschen bearbeitet.
const j = $input.first().json || {};
const ok = p => p.length <= 1000 && !p.startsWith('/') && !p.includes('\\') && !/[\u0000-\u001f\u007f*?{}]/.test(p) && /\.(pdf|csv)$/i.test(p)
  && !p.split('/').some(t => t === '' || t === '.' || t === '..' || t.length > 255);
const pfade = [];
for (const d of Array.isArray(j.dateien) ? j.dateien : []) {
  const p = String(d ?? '');
  if (p && ok(p) && !pfade.includes(p)) pfade.push(p);
}
return pfade.length ? pfade.slice(0, 200).map(pfad => ({ json: { aktion: 'pruefen', bereich: 'ally', pfad } })) : [{ json: { leer: true } }];

// Lösch-Aufträge (SHOPIFY 5, Migration 109/123): nur Pfade, die SPEICHER 1 eben eindeutig als DATEI gemeldet hat – nie Ordner, nie Fehler, im Zweifel nie.
// Eindeutig heißt (Nachprüfung N9): eigener Server „datei: true“ („[ -f ]“); WebDAV positive Größe UND typ_bekannt (resourcetype in einem propstat mit Status 200)
// UND keine collection in irgendeiner Form (dann meldet SPEICHER 1 ordner). Ein DELETE auf einen WebDAV-Ordner löscht rekursiv – darum diese Strenge.
// Jede Datei gibt danach die Datenbank einzeln frei.
const P = $input.all().map(x => x.json || {});
const groesse = r => r.bytes !== undefined && r.bytes !== null && r.bytes !== '' && Number.isFinite(Number(r.bytes)) && Number(r.bytes) > 0;
const istDatei = r => r.ok !== false && r.aktion === 'pruefen' && r.vorhanden === true && r.ordner === false && /\.(pdf|csv)$/i.test(String(r.pfad || ''))
  && (r.datei === true || (groesse(r) && r.typ_bekannt === true));
const loeschen = P.filter(istDatei);
return loeschen.length ? loeschen.map(r => ({ json: { pfad: String(r.pfad) } })) : [{ json: { leer: true } }];

// Löschauftrag (SHOPIFY 5, Migration 109): die eben freigegebene Datei an SPEICHER 1 (eine Datei je Durchgang der Schleife).
const f = ($input.first().json || {}).f || {};
return [{ json: { aktion: 'loeschen', bereich: 'ally', pfad: String(f.pfad || '') } }];

// Gesperrt (SHOPIFY 5, Migration 109): die Datenbank hat die Datei nicht freigegeben – nicht löschen, Grund für den Abschluss merken.
const f = ($input.first().json || {}).f || {};
return [{ json: { aktion: 'loeschen', pfad: String(f.pfad || ''), ok: false, gesperrt: true, fehler: String(f.grund || 'Nicht freigegeben.').slice(0, 300) } }];

// Ergebnis (SHOPIFY 5, Migration 109): je Pfad ein Status für shopify_loeschauftrag_abschliessen – geloescht, fehlte (schon weg, kein Fehler), ordner (nie
// gelöscht), gesperrt (nicht freigegeben, mit Grund) oder fehler (mit Grund). Eingang: alle Durchgänge der Schleife „Je Datei“ (oder ein leeres Item).
// Die Datenbank löscht nur Elemente, deren Dateien alle gelöscht sind oder schon fehlten; die anderen bleiben mit Grund im Papierkorb.
const E = $('Start').first().json || {};
const pruef = $('Dateien prüfen (SPEICHER 1)').isExecuted ? $('Dateien prüfen (SPEICHER 1)').all().map(x => x.json || {}) : [];
const loesch = $input.all().map(x => x.json || {}).filter(j => j.aktion === 'loeschen');
const st = {};
for (const r of pruef) {
  const p = String(r.pfad || ''); if (!p) continue;
  if (r.ok === false || r.weg === 'fehler') st[p] = { pfad: p, status: 'fehler', fehler: String(r.fehler || 'Prüfen fehlgeschlagen').slice(0, 300) };
  else if (r.vorhanden === false) st[p] = { pfad: p, status: 'fehlte' };
  else if (r.ordner === true) st[p] = { pfad: p, status: 'ordner' };
  // N9: nicht eindeutig als Datei erkannt (wie in „Lösch-Aufträge“) – Ally löscht im Zweifel nicht
  else if (r.datei !== true && !(Number(r.bytes) > 0 && r.typ_bekannt === true))
    st[p] = { pfad: p, status: 'fehler', fehler: 'nicht gelöscht – der Speicherort meldet nicht eindeutig, dass es eine Datei ist (Größe oder Dateityp fehlt)' };
  else st[p] = { pfad: p, status: 'fehler', fehler: 'nicht gelöscht' };
}
for (const r of loesch) {
  const p = String(r.pfad || ''); if (!p || !st[p] || st[p].status !== 'fehler') continue;
  if (r.gesperrt === true) st[p] = { pfad: p, status: 'gesperrt', fehler: String(r.fehler || 'Nicht freigegeben.').slice(0, 300) };
  else if (r.ok === false || r.weg === 'fehler') st[p] = { pfad: p, status: 'fehler', fehler: String(r.fehler || 'Löschen fehlgeschlagen').slice(0, 300) };
  else st[p] = { pfad: p, status: r.vorhanden === false ? 'fehlte' : 'geloescht' };
}
return [{ json: { werte: [String(E.token || ''), String(E.auftrag || ''), JSON.stringify(Object.values(st))] } }];
